<?php

  // spectrum - One-sided direct DFT for 1..1024 real samples with required sampleRate in Hz. Window defaults Hann symmetric; rectangular is explicit. scaling=amplitude divides by sum(window), doubling non-DC/non-Nyquist amplitudes. scaling=power divides squared magnitude by N×sum(window²), doubling those same bins; rectangular-bin powers sum to input mean square. It is power per bin, not density per Hz. Phase uses the negative-exponent DFT. Returns frequency k×sampleRate/N. Uniform sampling is assumed; above-Nyquist content aliases. Zero-gain short windows fail.
  //
  // `padSignal('spectrum',[0,1,0,-1,0,1,0,-1],['sampleRate'=>8,'window'=>'rectangular','scaling'=>'amplitude'])`

return ['options'=>['sampleRate','window','periodic','scaling'],'call'=>function($input,$options,&$state){$samples=padSignalSamples($input,$state,1024);$n=count($samples);$rate=padSignalRate($options,TRUE);$name=$options['window']??'hann';$periodic=$options['periodic']??FALSE;$scaling=$options['scaling']??'amplitude';if(!in_array($scaling,['amplitude','power'],TRUE))throw new InvalidArgumentException('scaling is amplitude or power');$weights=padSignalWindowCoefficients($n,$name,$periodic,$state);$sum=array_sum($weights);$energy=array_sum(array_map(fn($w)=>$w*$w,$weights));if($sum<=0||$energy<=0)throw new InvalidArgumentException('window has zero gain for this sample length');$bins=[];
 for($k=0;$k<=intdiv($n,2);$k++){$real=$imag=$cr=$ci=0.0;foreach($samples as $i=>$v){padSignalTick($state);$angle=2*M_PI*$k*$i/$n;$v*=$weights[$i];padSignalAccumulate($real,$cr,$v*cos($angle));padSignalAccumulate($imag,$ci,-$v*sin($angle));}$magnitude=hypot($real,$imag);$factor=$k===0||($n%2===0&&$k===$n/2)?1:2;$value=$scaling==='amplitude'?$factor*$magnitude/$sum:$factor*($magnitude/sqrt($n*$energy))**2;$bins[]=['bin'=>$k,'frequency'=>$k*$rate/$n,'value'=>$value,'phase'=>atan2($imag,$real)];}
 return ['status'=>'ok','method'=>'direct one-sided DFT','bins'=>$bins,'sampleRate'=>$rate,'samples'=>$n,'window'=>$name,'periodic'=>$periodic,'scaling'=>$scaling,'coherentGain'=>$sum/$n,'frequencyResolution'=>$rate/$n,'assumption'=>'uniformly sampled real data; frequencies above Nyquist alias'];}];
